  ["data.otservbr.global.npc.a.dragon.mother.L58.203"] = "Greetings humans! Consider yourselfs lucky, I'm in need of {help}.",
  ["data.otservbr.global.npc.a.dragon.mother.L62.204"] = "Grrr.",
  ["data.otservbr.global.npc.a.dragon.mother.L65.205"] = "You have done me a favour and the knowledge you are seeking shall be yours. I melted the ice for you, you can pass now.",
