  ["data.otservbr.global.npc.a.fading.memory.L53.1295"] = "Oh...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L71.1052"] = "Chhchh?",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L72.1053"] = "Chh...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L73.1054"] = "Chh...",
  ["data.otservbr.global.npc.a.fluffy.squirrel.L74.1055"] = "Chchch. Chh! <you're not sure, but it seems that squirrel wants to trade your valuable acorns for useless stones that it found and considered uneatable>",
  ["data.otservbr.global.npc.a.frog.L57.1456"] = "*sigh* Yet another dumb adventurer.",
  ["data.otservbr.global.npc.a.frog.L58.1457"] = "Yeah, good bye and don't come again!",
  ["data.otservbr.global.npc.a.frog.L59.1458"] = "Hah! That idiot finally left.",
  ["data.otservbr.global.npc.a.ghostly.sage.L60.1103"] = "Ah, I feel a mortal walks these ancient halls again. Pardon me, I barely notice you. I am so lost in my thoughts.",
  ["data.otservbr.global.npc.a.ghostly.sage.L61.1104"] = "Good bye.",
  ["data.otservbr.global.npc.a.ghostly.sage.L62.1105"] = "Farewell then.",
  ["data.otservbr.global.npc.a.ghostly.woman.L62.1178"] = "I feel you. I hear your thoughts. You are ... alive.",
  ["data.otservbr.global.npc.a.ghostly.woman.L63.1179"] = "Alone ... so alone. So cold.",
  ["data.otservbr.global.npc.a.ghostly.woman.L64.1180"] = "Alone ... so alone. So cold.",
