  ["data.otservbr.global.npc.a.majestic.warwolf.L83.37"] = "Interesting. A human who can speak the language of wolves.",
  ["data.otservbr.global.npc.a.majestic.warwolf.L84.38"] = "YOOOOUHHOOOUU!",
  ["data.otservbr.global.npc.a.majestic.warwolf.L85.39"] = "YOOOOUHHOOOUU!",
  ["data.otservbr.global.npc.a.nightmare.scion.L56.996"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.nightmare.scion.L65.997"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.nightmare.scion.L72.998"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.prisoner.L138.261"] = "Wait! Don't leave! I want to tell you about my surreal numbers.",
  ["data.otservbr.global.npc.a.prisoner.L139.262"] = "Good bye! Don't forget about the secrets of mathemagics.",
  ["data.otservbr.global.npc.a.prisoner.L140.263"] = "Huh? What? I can see! Wow! A non-mino. Did they {capture} you as well?",
  ["data.otservbr.global.npc.a.restless.soul.L53.44"] = "Uhhhh...",
  ["data.otservbr.global.npc.a.restless.soul.L56.45"] = "Ahhhh! At last someone that can listen to my {story}!",
  ["data.otservbr.global.npc.a.sleeping.dragon.L51.150"] = "ZzzzZzzZz...chrrr...",
  ["data.otservbr.global.npc.a.sleeping.dragon.L53.151"] = "Greetings, {wayfarer}.",
  ["data.otservbr.global.npc.a.strange.chalice.L117.1623"] = "Hi? What do you mean 'hi' - can't you see I am a... I have to lower my voice. Did it occur to you, that this 'chalice' does not want to be disturbed?! Leave me alone!",
  ["data.otservbr.global.npc.a.swan.L95.88"] = "I salute you, mortal being.",
  ["data.otservbr.global.npc.a.sweaty.cyclops.L227.68"] = "Hum Humm! Welcume lil' |PLAYERNAME|.",
  ["data.otservbr.global.npc.a.sweaty.cyclops.L228.69"] = "Good bye lil' one.",
  ["data.otservbr.global.npc.a.vulcongra.L56.934"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.vulcongra.L65.935"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.vulcongra.L72.936"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.weakened.forest.fury.L122.711"] = "I greet you, human. This is a time of distress, more than ever are we in need of guardians to protect us and our world.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L80.1421"] = "What is this? An optically challenged entity called |PLAYERNAME|. How fascinating!",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L81.1422"] = "Wait right there. I will eat you after writing down what I found out.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L82.1423"] = "Wait right there. I will eat you after writing down what I found out.",
  ["data.otservbr.global.npc.a.wyrm.L56.1560"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.wyrm.L65.1561"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.a.wyrm.L72.1562"] = "Pssst! Keep it down! <gives you an elaborate report on monster activity>",
  ["data.otservbr.global.npc.ahmet.L182.407"] = "Be mourned pilgrim in flesh. I'm selling general goods. Just ask me for a {trade}.",
  ["data.otservbr.global.npc.ajax.L58.355"] = "You back. You know, you right. Brother is right. Fist not always good. Tell him that!",
  ["data.otservbr.global.npc.ajax.L61.356"] = "Whatcha do in my place?",
  ["data.otservbr.global.npc.al.dee.L166.596"] = "Bye, bye.",
  ["data.otservbr.global.npc.al.dee.L167.597"] = "Bye, bye |PLAYERNAME|.",
  ["data.otservbr.global.npc.al.dee.L168.598"] = "Take a look in the trade window to your left.",
  ["data.otservbr.global.npc.albinius.L267.1035"] = "Greetings, pilgrim. Welcome to the halls of hope. We are the keepers of this {temple} and welcome everyone willing to contribute.",
  ["data.otservbr.global.npc.albinius.L268.1036"] = "Oh... farewell, child.",
  ["data.otservbr.global.npc.alesar.L206.1591"] = "Finally.",
  ["data.otservbr.global.npc.alesar.L207.1592"] = "Finally.",
  ["data.otservbr.global.npc.alesar.L208.1593"] = "At your service, just browse through my wares.",
  ["data.otservbr.global.npc.alexander.L171.1567"] = "Hi there |PLAYERNAME|, and welcome to the {magic} store.",
  ["data.otservbr.global.npc.alexander.L172.1568"] = "See you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L173.1569"] = "See you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L174.1570"] = "Of course, just browse through my wares. Or do you want to look only at",
  ["data.otservbr.global.npc.alia.L148.1158"] = "Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.alia.L149.1159"] = "Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.alia.L150.1160"] = "May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.alkestios.L130.1473"] = "Nature's blessing, traveller! May you not be affected by any sinister force.",
  ["data.otservbr.global.npc.alkestios.L131.1474"] = "May your path always be even.",
  ["data.otservbr.global.npc.alkestios.L132.1475"] = "May your path always be even.",
  ["data.otservbr.global.npc.altar.L83.730"] = "Kneel before the all-devouring power of blooded decay.",
  ["data.otservbr.global.npc.altar.L84.731"] = "Bye.",
  ["data.otservbr.global.npc.altar.L85.732"] = "Bye, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alyxo.L210.798"] = "Well, bye then.",
  ["data.otservbr.global.npc.alyxo.L53.795"] = "How could I help you?",
  ["data.otservbr.global.npc.alyxo.L56.796"] = "How could I help you?",
  ["data.otservbr.global.npc.alyxo.L59.797"] = "How could I help you?",
  ["data.otservbr.global.npc.amanda.L200.1226"] = "Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.amanda.L201.1227"] = "Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.amanda.L202.1228"] = "May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L86.343"] = "Greetings, friend.",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L87.344"] = "Well, bye then.",
  ["data.otservbr.global.npc.amber.L426.528"] = "Yeah, see you later.",
  ["data.otservbr.global.npc.amber.L427.529"] = "See you later, |PLAYERNAME|.",
  ["data.otservbr.global.npc.amber.L428.530"] = "Oh hello, nice to see you |PLAYERNAME|. Are you here to hear some stories of my {adventures} or do you need {help}?",
  ["data.otservbr.global.npc.anderson.L100.133"] = "Ahoi, young man |PLAYERNAME| and welcome to the Nordic Tibia Ferries. If you need a {passage}, let me know.",
  ["data.otservbr.global.npc.anderson.L101.134"] = "Good bye. You are welcome.",
  ["data.otservbr.global.npc.andrew.lyze.L101.514"] = "Hello, I am the warden of this {monument}. The {sarcophagus} in front of you was established to prevent people from going {down} there. But I doubt that this step is sufficient.",
  ["data.otservbr.global.npc.andrew.lyze.L103.515"] = "Well, let's see if your mission was successful. Just bring me all needed {materials}.",
  ["data.otservbr.global.npc.andrew.lyze.L105.516"] = "If you dug up all three crystals of sufficient quantity and obtained the poison gland, the charging of your compass can start! For the very first time it will be charged by the violet crystal. Ready to {unleash} the power of the crystals?",
  ["data.otservbr.global.npc.andrew.lyze.L107.517"] = "Greetings.",
  ["data.otservbr.global.npc.andrew.lyze.L263.518"] = "Well, bye then.",
  ["data.otservbr.global.npc.andrew.lyze.L264.519"] = "Good bye.",
