  ["data.otservbr.global.npc.santiago.L101.959"] = "Welcome back! Where were we... ? Ah, right, I asked you if you saw your 'level up'! You did, {right}?",
  ["data.otservbr.global.npc.santiago.L104.960"] = "Welcome back! Where were we... ? Ah, right, I asked you if those nasty cockroaches {hurt} you! Did they?",
  ["data.otservbr.global.npc.santiago.L107.961"] = "Welcome back! Where were we... ? Ah, right, I asked you if I should demonstrate some damage on you. Let's do it, {okay}?",
  ["data.otservbr.global.npc.santiago.L110.962"] = "Welcome back! Where were we... ? Ah, right, I was about to show you how you regain health, right?",
