  ["data.otservbr.global.npc.santiago.L116.964"] = "Welcome back! Where were we... ? Ah, right, I asked you if you saw Zirella! Did you?",
  ["data.otservbr.global.npc.santiago.L119.965"] = "Hello again, |PLAYERNAME|! It's great to see you. If you like, we can chat a little. Just use the highlighted {keywords} again to choose a {topic}.",
