  ["data.otservbr.global.npc.santiago.L90.958"] = "Good job! For that, I'll grant you 100 experience points! Oh - what was that? I think you advanced a level, {right}?",
  ["data.otservbr.global.npc.sarina.L86.73"] = "Oh, please come in, |PLAYERNAME|. What can I do for you? If you need adventure equipment, ask me for a {trade}.",
