  ["data.otservbr.global.npc.xorlosh.L92.606"] = "See you my friend.",
  ["data.otservbr.global.npc.xorlosh.L93.607"] = "Who are you? Are you a genius in mechanics? You don't look like one.",
  ["data.otservbr.global.npc.yaman.L167.634"] = "Farewell, human.",
  ["data.otservbr.global.npc.yaman.L168.635"] = "Farewell, human.",
  ["data.otservbr.global.npc.yaman.L169.636"] = "At your service, just browse through my wares.",
  ["data.otservbr.global.npc.yasir.L830.924"] = "Si, jema ze harun. <waves>",
  ["data.otservbr.global.npc.yberius.L169.1364"] = "Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.yberius.L170.1365"] = "Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.yberius.L171.1366"] = "May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.yoem.L61.188"] = "Hello |PLAYERNAME|! Do you need some equipment for your house?",
  ["data.otservbr.global.npc.yoem.L62.189"] = "Have a look. Most furniture comes in handy kits. Just use them in your house to assemble the furniture. Do you want to see only a certain {type} of furniture?",
  ["data.otservbr.global.npc.yonan.L137.684"] = "How could I help you?",
  ["data.otservbr.global.npc.yonan.L140.685"] = "How could I help you?",
  ["data.otservbr.global.npc.yonan.L143.686"] = "How could I help you?",
  ["data.otservbr.global.npc.yonan.L216.687"] = "Well, bye then.",
