  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L13.2084"] = "This crate belongs to Angelo. You should talk to him before taking something out.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L7.2082"] = "Perfect! You took a wonderful loupe from this crate.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L10.2103"] = "So for a small expense allowance you'll get it back. Just talk to Iwar in Kazordoon for further information.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L11.2104"] = "Ask him: Has the cat got your tongue?",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L7.2100"] = "Dear curator, this recently opened museum is a really nice place to be.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L8.2101"] = "But wait! What about the empty space in front of you? What a pity!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L9.2102"] = "It seems that somebody has removed one of the beautiful pictures. But come on! You have the money and we need it.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L23.2096"] = "The strange symbol in the wall in the back glows violently.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L24.2097"] = "The cult object just lies there quietly. The dangerous area around it has been all but dissolved.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L25.2098"] = "As you reach out to touch the cult object, a surge of energy burst from the skull. You banished its power.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L19.2122"] = "Nothing special. This picture looks genuine.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L24.2123"] = "This is it. It looks like it was painted by a child!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.misguided.L62.2109"] = "You paralyse the bully and the amulet reveals the true face of the creature behind the possession of this misguided creature.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.torch.L18.2116"] = "You hear a loud grinding sound not very far from you. something very heavy seems to have moved.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.begin.task.L36.2106"] = "The amulet burns your skin. It hungers for energy right now, gather a large amount of energy as fast as possible to charge it.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.check.oasis.L10.2108"] = "You have found a lovely oasis with green fauna and juicy fruit. You didn't expect that.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L31.2117"] = "With you being the vessel binding the power of whitered souls, you step through the magic barrier.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L35.2118"] = "The combined powers of decaying souls roaming these halls may help breach this barrier, it needs but a vessel to bind them.",
