  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.keyCheck.L22.1831"] = "You need to use the mechanism of the pillar itself to turn both keys at once.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.keyCheck.L26.1832"] = "You reach for the onyx and trigger and enormous discharge of raw energy. It is now possible to traverse the portal in this tomb.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.magicalPaint.L24.1837"] = "Carefully you paint over the picture. As you are doing so the flat paiting deepens. It looks now like a room you can enter.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.magicalPaint.L38.1838"] = "This isn't a normal paiting anymore. By using magical paint you transformed it into a portal and can easily pass it.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.oldLock.L15.1845"] = "You insert the old lock into the door. It fits perfectly.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L108.1859"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L115.1860"] = "As Medusa's Ointment takes effect, the door is unpetrified. You can use it now.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L128.1861"] = "The lock in this door is missing. Perhaps you can find a matching lock somewhere?",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.questDoors.L141.1862"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.rosebushUse.L16.1851"] = "You plant the rosebush into the fresh soil. The green portal glows brighter. Perhaps you may pass it now.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.sacrophagusUse.L41.1840"] = "The curse of disturbing this fragile, ancient peace is your price to pay!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.sacrophagusUse.L47.1841"] = "The opening of the last sarcophagus still haunts you. Wait some time for your spirits to return.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L37.1833"] = "There is not enough ectoplasm left to fill it in the bucket.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L43.1834"] = "There is not enough ectoplasm left to fill it in the bucket.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L49.1835"] = "The ectoplasm all over this egg was already seeping inside the cocoon itself. You manage to fill soem of it into the bucket.",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.strangeBucket.L69.1836"] = "You pour all of the ectoplasm over yourself. Without the bucket you cannot stabilise it, you need to hurry until it dissolves!",
  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.sunFruit.L21.1829"] = "You have found some",
