  ["data.otservbr.global.scripts.quests.the.explorer.society.movements.calassa.L18.1912"] = "You must wear an underwater exploration helmet in order to dive.",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.lair.entrance.L5.1761"] = "You are not worthy to enter in The First Dragon's Lair yet.",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.rewards.L44.1756"] = "You are not eligible to claim these rewards yet.",
