  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.rewards.L69.1759"] = "You found",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.rewards.L71.1760"] = "The chest is empty.",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.sacrifice.items.L17.1767"] = "You already sacrificed this item to pass.",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.sacrifice.items.L22.1768"] = "You're plunging",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.sacrifice.items.L33.1769"] = "You're plunging",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.treasure.chest.L112.1763"] = "You found",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.treasure.chest.L116.1764"] = "You found",
  ["data.otservbr.global.scripts.quests.the.first.dragon.actions.treasure.chest.L96.1762"] = "The",
  ["data.otservbr.global.scripts.quests.the.first.dragon.movements.last.teleport.L24.1765"] = "This teleport is only available between January 14 and February 12.",
  ["data.otservbr.global.scripts.quests.the.first.dragon.movements.last.teleport.L35.1766"] = "You have to wait to challenge The First Dragon again!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.ashes.L9.2012"] = "The ashes swirl with a life of their own, mixing with the sparks of the altar.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.brain.L13.2005"] = "No brains",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.brain.L16.2006"] = "You have already got your brain",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.brain.L8.2004"] = "<brzzl> <frzzp> <fsssh>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.caixa.L5.2020"] = "You have found an incantation fragment.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.candles.L9.2009"] = "Reading the parchment, you identify three human tallow candles and pocket them.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.cape.L5.2019"] = "You now look like a Necromancer.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.chalk.L9.2014"] = "The flame wavers as it engulfs the chalk. Strange ashes appear beside it.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.flask.L10.2002"] = "Done! Report back to Omrabas.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.hallowed.L9.2003"] = "The flames roar and eat the bone hungrily. The Dark Lord is satisfied with your gift",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.inscriptions.L13.2024"] = "The words seem to flutter. One word stays in your mind: floating",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.inscriptions.L5.2022"] = "The words seem to breathe, stangely. One word stays in your mind: bronze",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.inscriptions.L9.2023"] = "The words seem to glow slightly. A name fixes in your mind: Takesha Antishu",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key1.L8.2026"] = "<swoosh> <oomph> <cough, cough>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key2.L14.2016"] = "Get out of my room!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key2.L9.2015"] = "An invisible hand pulls you inside.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.palanca.L6.2025"] = "<sizzle> <fizz>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids1.L17.2013"] = "<sizzle> <fizz>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids2.L18.2027"] = "<screeeech> <squeak> <squeaaaaal>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids2.L21.2028"] = "Mission already completed here!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.sacrifice.L7.2011"] = "The scroll burns to dust. The magic stutters. Omrabas' soul flees to his old hideaway.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.scroll.L6.2017"] = "Somebody left a card. It says: Looking for the scroll? Come find me. Take the stairs next to the students. Dorm.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.statue.L12.2018"] = "<BOOOOOOOONGGGGGG> A slow throbbing, like blood pulsing, runs through the floor.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.tears.L9.2021"] = "The dragon tears glow and disappear. The old powers are appeased.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.tincture.L9.2010"] = "You crash the vial and spill the blood tincture. This altar is anointed.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.movements.dormitory.teleport.L13.2007"] = "You should hurry, try not to dwell here any longer than a few minutes.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.movements.dormitory.teleport.L16.2008"] = "The teleport is accessible only once.",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.treasure.L22.1794"] = "It is impossible to take along all of the treasures here. But you pick out",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.treasure.L40.1795"] = "You try to pick a treasure, but you hear further dragons approaching. You should kill some more before picking out something.",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.warrior.skeleton.L15.1793"] = "The dead explorer is empty.",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.warrior.skeleton.L5.1792"] = "You have discovered a deceased warrior's skeleton. It seems he tried to hunt the dragons around here - and failed.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.actions.ore.wagon.L103.2158"] = "You don't have permission to use this yet.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.actions.ore.wagon.L176.2159"] = "You don't know how to use this yet.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.moviments.elevator.L23.2160"] = "You don't know how to use this yet.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.moviments.ore.wagon.L11.2157"] = "You have found the entrance to the hidden city of Beregar and may now use the ore wagon.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L47.2241"] = "You should set a new bait first.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L49.2242"] = "Oops! You lost it.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L53.2243"] = "You see water as far as the eye can reach. No sea serpent in sight.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L66.2244"] = "It's getting away! You should tell the captain to gain speed!",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L72.2245"] = "There are multiple shadows under the surface. This has to be the right location.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.movements.teleports.L26.2238"] = "You have to wear a helmet of the deep.",
