  ["data.otservbr.global.scripts.quests.the.inquisition.quest.actions.ungreez.door.L20.1772"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.lost.brother.movement.find.remains.L10.1984"] = "You stumble over some old bones. Something is carved into the stone wall here: 'Tarun, my brother, you were right. She's evil.'",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.arena.L62.2164"] = "You already finished this battle.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.arena.L67.2165"] = "The arena is already in use.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.hidden.note.L9.2170"] = "You have found a piece of paper.",
