  ["data.otservbr.global.scripts.quests.the.new.frontier.action.outfit.L13.2167"] = "You already taken the outfit, ask about mission for Chrak.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.movement.jail.exit.L22.2168"] = "You don't have access to this area.",
