  ["data.otservbr.global.scripts.quests.the.order.of.lion.moveevent.drume.entrance.L5.1644"] = "You've been into the skirmish in the last 10 hours.",
  ["data.otservbr.global.scripts.quests.the.outlaw.camp.actions.the.outlaw.camp.quest.L24.1909"] = "You have found a bag.",
  ["data.otservbr.global.scripts.quests.the.paradox.tower.movement.sacrifice.skulls.L24.1751"] = "One of the toxic salt seas in Krailos carries fresh and clean water again. The ogres' water supply is ensured for now",
  ["data.otservbr.global.scripts.quests.the.pits.of.inferno.quest.movements.pumin.teleport.L15.2236"] = "To enter Pumin's domain you must gain permission from the bureaucrats.",
  ["data.otservbr.global.scripts.quests.the.postman.missions.quest.actions.waldos.posthorn.L6.2152"] = "You found Waldo's posthorn.",
