  ["data.otservbr.global.scripts.quests.the.primal.ordeal.creaturescripts.magma.bubble.death.L17.2173"] = "Congratulations you received the Fire-Fighter Outfit.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L100.1698"] = "You have to wait a few minutes before you can pick up a new stone.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L103.1699"] = "You don't need any stones anymore. Rookgaard's defences have been fortified.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L129.1700"] = "You load the heavy stone on the catapult. Now, get another stone and find the remaining catapult.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L131.1701"] = "You loaded the last stone on the catapults. Time to return to Vascalir.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L138.1702"] = "You have already loaded a stone on this catapult. Look around on other roofs to find the remaining catapults.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L100.1727"] = "You rub the strange grease on your body. The spider queen will not be able to smell you for about 2 minutes. Hurry!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L105.1728"] = "You already retrieved some of the spider queen's web. No need to go back down there.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L126.1729"] = "Don't enter the lair without a protective grease. Use one of the stones to the north to become invisible to her.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L133.1730"] = "You already have the spider queen's web. You should go back to Vascalir and not take any further risks.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L154.1731"] = "You retrieved some of the spider queen's web. Hurry back before she can smell you again!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L75.1726"] = "You have no business down there.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L140.1691"] = "Oh no... you were too slow and the wolves caught up with you. You may try again.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L155.1692"] = "RUUUUUUUUUUUUUUUUUN!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L184.1693"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L189.1694"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L205.1695"] = "You got the war wolf leather - but you hear a scary howl behind you. Time to get out of here - FAST!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L230.1696"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L234.1697"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L72.1690"] = "You have no business down there.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L123.1741"] = "Fire in this stadium can be crossed without taking damage. Open the chest and get out of here!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L148.1742"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L152.1743"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L77.1739"] = "You're coughing so badly that you had to return upstairs. Take a few deep breaths and try again.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L97.1740"] = "This fire is much too hot to walk through it. Use the destroy field rune on the fire to weaken the flames!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L118.1734"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L122.1735"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L159.1736"] = "That should weaken the beam enough to make it collapse soon.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L161.1737"] = "This was the last beam. Now, get out of here before the cave collapses!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L169.1738"] = "You've already weakened this beam. Better leave it alone now so it won't collapse before you are out of here.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L74.1732"] = "You have no business down there.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L77.1733"] = "The cave has collapsed. It's not safe to go down there anymore.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L142.1747"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L144.1748"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L149.1749"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L91.1745"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L95.1746"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission11.sweet.poison.L59.1744"] = "You carefully gather some of the wasp poison. Bring it back to Vascalir.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L178.1703"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L183.1704"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L209.1705"] = "You knock the unsuspicious orc unconscious. Use him to disguise yourself as orc!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L217.1706"] = "You have no reason to do such an insidious thing.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L232.1707"] = "You look almost like an orc. It won't fool all orcs, but the stupid guardsman in front of the fortress should fall for it.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L277.1708"] = "This should be enough distraction for you to sneak into the fortress! Hurry up!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L310.1709"] = "You poisoned Kraknaknork's soup. This should weaken him immensely. Time to find his room.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L329.1710"] = "The berserker can't catch you anymore - but only for 20 seconds. You need to lure him away from the teleporter!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L362.1711"] = "As long as the orc berserker is near that teleporter, you can't enter.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L370.1712"] = "You're entering Kraknaknork's lair.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L483.1713"] = "An energy barrier somewhere temporarily disappeared.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L516.1714"] = "With his last energy, Kraknaknork pushes you out of his throne room. Hurry back and defeat him before he regains his power.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L549.1715"] = "A player is already inside the boss room.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L564.1716"] = "You're entering Kraknaknork's throne room. You have 5 minutes to kill him!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L595.1717"] = "You backed out of the fight. You may try again at any time.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L624.1718"] = "You may not use this teleporter yet.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L684.1719"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L686.1720"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L691.1721"] = "The",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L717.1722"] = "With Kraknaknork's final source of energy, you escape the fortress. Time to return to Vascalir.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L776.1723"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L778.1724"] = "You have found",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L783.1725"] = "The",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.bursting.at.the.seams.museum.actions.doors.L18.2291"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.actions.telescope.L6.2318"] = "The telescope provides a perfect view over the endless ocean - no land in sight",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L13.2312"] = "You see the scattered parts of a wrecked ship. Miraculously the ship telescope survived the wreckm it seems still to be intact.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L16.2313"] = "There are still some loose planks and hawsers. You can't use the raft like this, it will sink for sure.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L21.2314"] = "You use the hawser to lash up the loose planks. The raft should be seaworthy now.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L27.2315"] = "You see the scattered parts of a wrecked ship. Miraculously the ship telescope survived the wreck it seems still to be intact.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L30.2316"] = "Witout any points of orientation you will never find your way back. Try to find a way to improve your navigation.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.stepIn.L91.2317"] = "You must wait. Someone is challenging",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.library.area.movements.mazzinor.L13.2290"] = "The remains deporalize you temporaly.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L16.2302"] = "You tack the hair to the ebony fingerboard. The strands should be adquate to serve as strings.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L27.2303"] = "*There was once a maiden fair, with dark eyes and silken hair. Far away from home she died. No grave, no wake, no mourning.*",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L31.2304"] = "You are playing the Peacock Ballad and the portal opens.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L37.2305"] = "You are playing the bone fiddle.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.bonefiddle.L9.2301"] = "You attach the ebony wood to the skull. This should meet the requirements of a fingerboard.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.doors.L16.2310"] = "You do not have enough level.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.doors.L19.2311"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.actions.fragrance.L4.2306"] = "Hmmmm, what an infatuating fragrance!",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.movements.elemental.portals.L111.2308"] = "You can not use this portal yet.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.movements.elemental.portals.L142.2309"] = "You have discovered an old writing desk that contains an ancient map.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.lament.asuras.movements.elemental.portals.L92.2307"] = "You took too long, the battle has ended.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.doors.L47.2299"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.doors.L65.2300"] = "You can not use this boat yet.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.entrance.L17.2297"] = "Once more you mix the chalk with a drop of your blood and a bit of water and renew the symbol on the floor...",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.order.of.the.falcon.actions.entrance.L21.2298"] = "You can only use this entrance during the night.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.actions.chests.L20.2293"] = "You have found a",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.actions.chests.L22.2294"] = "It is empty.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.the.parth.of.defiances.desert.actions.doors.L22.2296"] = "The door seems to be sealed against unwanted intruders.",
