  ["data.otservbr.global.scripts.quests.the.shattered.isles.quest.action.tortoise.egg.nargor.L22.1916"] = "The",
  ["data.otservbr.global.scripts.quests.the.spike.tasks.movements.geomantic.charges.L38.1817"] = "You have charged your body with geomantic energy and can report about it.",
  ["data.otservbr.global.scripts.quests.the.spike.tasks.movements.spike.teleport.L38.1816"] = "Only premium accounts can use this teleporter.",
  ["data.otservbr.global.scripts.quests.the.tainted.soul.actions.star.herb.L12.1983"] = "You entwine the antler with fresh star herb.",
  ["data.otservbr.global.scripts.quests.the.thieves.guild.quest.actions.climbing.vine.L14.1750"] = "You can not enter a protection zone after attacking another player.",
  ["data.otservbr.global.scripts.quests.the.travelling.trader.actions.outlaw.camp.door.L9.2064"] = "The door seems to be sealed against unwanted intruders.",
  ["data.otservbr.global.scripts.quests.threatened.dreams.action.poacher.book.L9.2266"] = "You are placing the book on the table, hopefully the poachers will discover it soon.",
  ["data.otservbr.global.scripts.quests.threatened.dreams.action.poacher.notes.L7.2263"] = "You have found notes of a poacher.",
  ["data.otservbr.global.scripts.quests.threatened.dreams.action.whelp.fur.L13.2264"] = "You place the whelp fur in the stone's mouth and thus lay it to rest.",
  ["data.otservbr.global.scripts.quests.threatened.dreams.event.raven.herb.bush.L48.2262"] = "The raven herb cannot be collected right now.",
  ["data.otservbr.global.scripts.quests.threatened.dreams.movement.poacher.notes.L10.2265"] = "You discover a sleeping wolf and a gnawed skeleton in this tent. Could it be the one you are searching for?",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.actions.reward.L17.1810"] = "You have found a tinder box.",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.actions.ursagrodon.L32.1805"] = "You already have the obedience of ursagrodon.",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.actions.ursagrodon.L37.1806"] = "The ice cracked and the frozen creature with it - be more careful next time!",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.actions.ursagrodon.L43.1807"] = "You managed to melt about half of the ice blook. Quickly now, it's ice cold here and the ice block could freeze over again.",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.actions.ursagrodon.L46.1808"] = "You managed to melt almost the whole block, only the feet of the creature are still stuck in the ice. Finish the job!",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.actions.ursagrodon.L49.1809"] = "The freed ursagrodon look at you with glowing, obedient eyes.",
  ["data.otservbr.global.scripts.quests.tinder.box.quest.chyllfroest.movements.prohibit.entry.L14.1811"] = "You cannot pass here outside the period from April 1st to May 1st.",
  ["data.otservbr.global.scripts.quests.wrath.of.the.emperor.actions.mission11.payback.time.lever.L19.1648"] = "The arena is already in use.",
  ["data.otservbr.global.scripts.quests.wrath.of.the.emperor.actions.mission12.just.rewards.L11.1650"] = "The wardrobe is empty.",
