  ["otclient_modules.key_edit_otui.tr_2"] = "Clear",
  ["otclient_modules.key_edit_otui.tr_3"] = "Ok",
  ["otclient_modules.key_edit_otui.tr_4"] = "This hotkey is already in use.",
  ["otclient_modules.key_edit_otui.tr_5"] = "This action must be bound to a single key.",
  ["otclient_modules.key_edit_otui.tr_6"] = "Mode: \"Chat On\"",
  ["otclient_modules.keybinds_otui.tr_1"] = "Reset",
  ["otclient_modules.keybinds_otui.tr_10"] = "There are two chat modes for each hotkey preset: Chat On and Chat\n Off.You can find a small button that tells you which chat mode is\n currently active on the right side of the entry line of the chat console.Press this button to switch between the two chat modes.\nOf course, you can also set a hotkey to toggle between Chat On and Off.\n- Chat On\nIn this mode, you will be able to write text in the entry line of the chat console.\nHowever, if you have assigned an action to a letter key, the action will be triggered.\n- Chat On*\nThis is the temporary Chat On mode.\nIn the default hotkey preset, the Return key switches between Chat Off and this mode.\nIf the chat mode is off and you press this hotkey, it temporarily activates the chat mode so that you can write one message in the console.\nAs soon as you press Return to send the message, your chat mode will be set to Chat Off again so that you can continue walking with WASD, for example.\n- Chat Off\nIn this mode, you will not be able to write any text in the entry line of the console, but you can use your predefined hotkeys to walk or cast spells, for example.\nYou can assign functions to all keys of your keyboard, e.g. walk with WASD.",
  ["otclient_modules.keybinds_otui.tr_11"] = "If you have named your hotkey presets the same like your\ncharacters and have checked this option, the preset with the same\nname as the corresponding character will be activated upon login\nautomatically.",
  ["otclient_modules.keybinds_otui.tr_12"] = "Auto-Switch Hotkey Preset",
  ["otclient_modules.keybinds_otui.tr_13"] = "Remove",
  ["otclient_modules.keybinds_otui.tr_14"] = "Rename",
  ["otclient_modules.keybinds_otui.tr_15"] = "Copy",
  ["otclient_modules.keybinds_otui.tr_16"] = "Add",
  ["otclient_modules.keybinds_otui.tr_2"] = "New Action",
  ["otclient_modules.keybinds_otui.tr_3"] = "Secondary Key",
  ["otclient_modules.keybinds_otui.tr_4"] = "Primary Key",
  ["otclient_modules.keybinds_otui.tr_5"] = "Action",
  ["otclient_modules.keybinds_otui.tr_6"] = "Type to search for a hotkey:",
  ["otclient_modules.keybinds_otui.tr_7"] = "There are two chat modes for each hotkey preset: Chat On and Chat \nOff. You can find a small button that tells you which chat mode is \ncurrently active on the right side of the entry line of the chat \nconsole. Press this button to switch between the two chat modes. Of \ncourse, you can also set a hotkey to toggle between Chat On and Off.\n\tChat On\n\t\tIn this mode, you will be able to write text in the entry line of\n the chat console. However, if you have assigned an action to \na letter key, the action will be \t\ttriggered.\n\n\n\tChat On\n\t\tThis is the temporary Chat On mode. In the default hotkey \npreset, the Return key switches between Chat Off and this\n mode. If the chat mode is off and you press \t\tthis hotkey, it \ntemporarily activates the chat mode so that you can write \none message in the console. As soon as you press Return to \nsend the message, your chat \t\tmode will be set to \nChat Off again so that you can continue walking with WASD, for\n example.\n\n\tChat Off\n\t\tIn this mode, you will not be able to write any text in the entry line of the\n console, but you can use your predefined\n hotkeys to walk or cast spells, for \t\texample. You can assign\n functions to all keys of your keyboard, e.g. walk with WASD",
  ["otclient_modules.keybinds_otui.tr_8"] = "Chat Mode Off",
  ["otclient_modules.keybinds_otui.tr_9"] = "Chat Mode On",
